pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address nonOwner, address target) public {
        vm.assume(nonOwner != c.owner());
        vm.assume(nonOwner != address(0));
        vm.assume(target != address(0));
        vm.assume(target != address(c));
        vm.assume(amount <= address(this).balance);

        vm.deal(nonOwner, amount);
        vm.prank(nonOwner);
        bool ok = true;
        try c.sendMoney(target, amount) {
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}
